#include <xc.h>
#include <stdint.h>

int main(void) {
    char c;

    // 1. Pines: RB13 y RB7 digitales; RB13 entrada (U1RX)
    ANSELB &= ~((1 << 13) | (1 << 7));
    TRISB |= 1 << 13;
    LATB |= 1 << 7;        // U1TX en reposo a 1 si el transmisor se inhabilita
    TRISB &= ~(1 << 7);    // RB7 salida (U1TX)

    // Remapeo de pines (secuencia SYSKEY)
    SYSKEY = 0xAA996655;   // Se desbloquean los registros
    SYSKEY = 0x556699AA;   // de configuración
    U1RXR = 3;             // U1RX conectado a RB13
    RPB7R = 1;             // U1TX conectado a RB7
    SYSKEY = 0x1CA11CA1;   // Se vuelven a bloquear

    // 2-5. Velocidad, formato y arranque
    U1BRG = 32;            // 9600 baudios (BRGH = 0)
    U1STAbits.URXEN = 1;   // Se habilita el receptor
    U1MODE = 0x8000;       // ON = 1, formato 8N1, BRGH = 0

    while (1) {
        if (U1STAbits.URXDA != 0) {       // ¿Ha llegado un carácter?
            c = U1RXREG;                  // Se lee (y se retira de la FIFO)
            U1STAbits.UTXEN = 1;          // Se habilita el transmisor
            U1TXREG = 'O';
            while (U1STAbits.TRMT == 0);  // Espera a que se envíe
            U1TXREG = 'K';
            while (U1STAbits.TRMT == 0);
            U1STAbits.UTXEN = 0;          // Se inhabilita al terminar
        }
    }
    return 0;
}

void initUART1(void) {
    // 1. Pines digitales y dirección
    ANSELB &= ~((1 << 13) | (1 << 7));  // RB13 y RB7 digitales
    TRISB |= 1 << 13;                   // RB13 entrada (U1RX)
    LATB |= 1 << 7;                     // U1TX en reposo a 1
    TRISB &= ~(1 << 7);                 // RB7 salida (U1TX)

    // 2. Remapeo (secuencia SYSKEY)
    SYSKEY = 0xAA996655;
    SYSKEY = 0x556699AA;
    U1RXR = 3;                          // U1RX conectado a RB13
    RPB7R = 1;                          // U1TX conectado a RB7
    SYSKEY = 0x1CA11CA1;

    // 3. Velocidad
    U1BRG = 32;                         // 9600 baudios (BRGH = 0)

    // 4. Interrupciones (vector 32 compartido RX/TX)
    IFS1bits.U1RXIF = 0;                // Borro flags por si acaso
    IFS1bits.U1TXIF = 0;
    IEC1bits.U1RXIE = 1;                // Habilito la interrupción del receptor
    IPC8bits.U1IP = 3;                  // Prioridad 3
    IPC8bits.U1IS = 1;                  // Subprioridad 1

    // 5. Modos y arranque
    U1STAbits.URXISEL = 0;              // Interrumpe con cada carácter recibido
    U1STAbits.UTXISEL = 2;              // Interrumpe cuando la FIFO de TX se vacía
    U1STAbits.URXEN = 1;                // Receptor habilitado
    U1STAbits.UTXEN = 1;                // Transmisor habilitado
    U1MODE = 0x8000;                    // Se arranca la UART (8N1)
}

#define TAM_CAD 80              // Tamaño máximo de la cadena a transmitir
static char cad_tx[TAM_CAD];
static int i_cad_tx = 0;        // Índice para la cadena de transmisión
static char car_rx = '\0';      // '\0' indica que no ha llegado nada

__attribute__((vector(32), interrupt(IPL3SOFT), nomips16))
void InterrupcionUART1(void) {
    if (IFS1bits.U1RXIF == 1) {           // Ha interrumpido el receptor
        car_rx = U1RXREG;
        IFS1bits.U1RXIF = 0;              // Se borra el flag
    }
    if (IFS1bits.U1TXIF == 1) {           // Ha interrumpido el transmisor
        if (cad_tx[i_cad_tx] == '\0') {   // Ha terminado la cadena
            IEC1bits.U1TXIE = 0;          // Para no entrar en bucle sin fin
            i_cad_tx = 0;                 // Listo para la siguiente cadena
            cad_tx[0] = '\0';             // Para no reenviarla de nuevo
        } else {
            U1TXREG = cad_tx[i_cad_tx];
            i_cad_tx++;
        }
        IFS1bits.U1TXIF = 0;              // Se borra el flag
    }
}

char getcUART(void) {           // Acceso a car_rx sin compartir la variable
    char car_ret;
    car_ret = car_rx;
    if (car_ret != '\0') {      // Ha llegado un carácter nuevo
        car_rx = '\0';          // Se marca como leído
    }
    return car_ret;
}

void putsUART(char s[]) {
    uint8_t i = 0;
    while (s[i] != '\0') {
        cad_tx[i] = s[i];
        i++;
    }
    cad_tx[i] = '\0';
    IEC1bits.U1TXIE = 1;        // Habilita la interrupción: comienza el envío
}

int main(void) {
    char c;

    LATA = 0; LATB = 0; LATC = 0;           // Salidas a 0
    TRISA = 0xFFFF; TRISB = 0xFFFF; TRISC = 0xFFFF;

    initUART1();                            // Drivers de periféricos

    INTCONbits.MVEC = 1;                    // Interrupciones multivector
    asm("ei");                              // Habilitación global, AL FINAL

    putsUART("Hola GITT\n");
    while (1) {
        c = getcUART();                     // '\0' si no ha llegado nada
        if (c == 'h') {
            putsUART("Hola!\n");
        }
        // ... resto de tareas del bucle de scan
    }
    return 0;
}

#define TAM_COLA 100
static char cola_rx[TAM_COLA], cola_tx[TAM_COLA];
static int icab_rx = 0, icol_rx = 0;    // Índices de la cola de recepción
static int icab_tx = 0, icol_tx = 0;    // Índices de la cola de transmisión

__attribute__((vector(32), interrupt(IPL3SOFT), nomips16))
void InterrupcionUART1(void) {
    if (IFS1bits.U1RXIF == 1) {                 // Receptor: meter en cola_rx
        if ((icab_rx + 1 == icol_rx) ||
            (icab_rx + 1 == TAM_COLA && icol_rx == 0)) {
            // La cola está llena: el carácter se pierde
        } else {
            cola_rx[icab_rx] = U1RXREG;         // Lee el carácter de la UART
            icab_rx++;
            if (icab_rx == TAM_COLA) {
                icab_rx = 0;                    // El buffer es circular
            }
        }
        IFS1bits.U1RXIF = 0;                    // Se borra el flag
    }
    if (IFS1bits.U1TXIF == 1) {                 // Transmisor: sacar de cola_tx
        if (icol_tx != icab_tx) {               // Hay datos pendientes
            U1TXREG = cola_tx[icol_tx];
            icol_tx++;
            if (icol_tx == TAM_COLA) {
                icol_tx = 0;
            }
        } else {                                // Se ha vaciado la cola
            IEC1bits.U1TXIE = 0;                // Para evitar el bucle sin fin
        }
        IFS1bits.U1TXIF = 0;                    // Se borra el flag
    }
}

char getcUART(void) {
    char c;
    if (icol_rx != icab_rx) {       // Hay datos nuevos
        c = cola_rx[icol_rx];
        icol_rx++;
        if (icol_rx == TAM_COLA) {
            icol_rx = 0;
        }
    } else {
        c = '\0';                   // No ha llegado nada
    }
    return c;
}

void putsUART(char s[]) {
    uint8_t i = 0;
    while (s[i] != '\0') {
        if ((icab_tx + 1 == icol_tx) ||
            (icab_tx + 1 == TAM_COLA && icol_tx == 0)) {
            break;                  // Cola llena: se aborta el resto del envío
        }
        cola_tx[icab_tx] = s[i];    // Copia el carácter en la cola
        i++;
        icab_tx++;
        if (icab_tx == TAM_COLA) {
            icab_tx = 0;
        }
    }
    IEC1bits.U1TXIE = 1;            // Comienza (o continúa) la transmisión
}
